insert into public.programs (id, kind, name, college, catalog, min_total_credits, min_gpa, notes, source_url, sort_order, excluded_programs, parent_id) values
('minor-architectural-studies', 'minor', 'Architectural Studies Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 12, 2.0, 'Offered by the Knowlton School. No approval needed to declare; tell your advisor. Courses not on the sheet need Knowlton''s approval (Jessica Baer-Graves). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/architectural-studies-eng', 300, '{}'::text[], null),
('minor-aviation', 'minor', 'Aviation Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 15, 2.0, 'For students outside the Aviation major; flight training isn''t available in the minor. Many courses have prerequisites beyond the minor. The department''s site suggests interest areas (drones/UAS, air traffic control, aviation management, weather and performance, dispatching, safety and human factors); none is required. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/aviation-eng', 301, array['eng-aviation']::text[], null),
('minor-biomedical-engineering', 'minor', 'Biomedical Engineering Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 12, 2.0, 'For students outside the BME major. Prerequisites: calculus (MATH 1151 and 1172, or an equivalent sequence), MATH 2568, 2173, or 2177; CHEM 1210 and 1220 (or equivalent); PHYSICS 1250 (or equivalent); BIOLOGY 1113; ENGR 1181 and 1182 (or equivalent); MECHENG 2010 or 2040. Declare with Melissa Crohen, who also enrolls you in BIOMEDE 2000. Plan early; the minor can take two years. No substitutions for listed courses. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/biomedical-engineering-eng', 302, array['eng-biomedical']::text[], null),
('minor-city-and-regional-planning', 'minor', 'City and Regional Planning Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 12, 2.0, 'Offered by the Knowlton School. No approval needed; tell your advisor so it''s tracked on your degree audit. Substitutions need the section''s approval. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/city-and-regional-planning-eng', 303, '{}'::text[], null),
('minor-computer-science', 'minor', 'Computer Science Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 16, 2.0, 'Offered by Computer Science and Engineering for students in other majors (formerly the Computer and Information Science minor). Prerequisites: MATH 1151 or 1161.01, and CSE 1222, 1223, or 1224. Minor students don''t get priority enrollment in CSE courses. Courses not on the sheet need CSE''s approval (compsciadvising@osu.edu). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/computer-science', 304, array['eng-cse']::text[], null),
('minor-computational-science', 'minor', 'Computational Science Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 18, 2.0, 'Interdisciplinary minor administered by Arts and Sciences Advising (Ralph Regula School of Computational Science); file the minor form with an ASC advisor. All courses except CSE 1221 must be 2000-level or above. Requests for other courses go to Greg Kilcup (kilcup.1@osu.edu). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor is open to any major, but still needs 12 credit hours distinct from the major. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/computational-science', 305, '{}'::text[], null),
('minor-engineering-sciences', 'minor', 'Engineering Sciences Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 15, 2.0, 'For non-engineering students. Requires a first calculus course (MATH 1131 or 1151). The program advisor, Dr. Dale Masel (masel.2@osu.edu), approves your course choices and signs the minor form. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to 6 credit hours. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/engineering-sciences-eng', 306, array['eng-civil', 'eng-environmental', 'eng-mechanical', 'eng-aerospace', 'eng-welding', 'eng-ece', 'eng-engphys', 'eng-materials', 'eng-fabe', 'eng-cse', 'eng-chemical', 'eng-ise', 'eng-biomedical', 'eng-aviation']::text[], null),
('minor-environmental-engineering', 'minor', 'Environmental Engineering Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 15, 2.0, 'Prerequisites, done before the minor: MATH 1151 and CHEM 1210 and 1220 (or CHEM 1250). Civil Engineering students who use CIVILEN 3130 and ENVENG 3200 in their major take 3 more elective hours. Engineering majors may overlap 6 credit hours with their degree''s electives. Declare with Barry Tolchin (tolchin.5@osu.edu). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/environmental-engineering-eng', 307, array['eng-environmental']::text[], null),
('minor-humanitarian-engineering', 'minor', 'Humanitarian Engineering Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 16, 2.0, 'Run by Global Engineering (global.CoE@osu.edu). Courses not listed can be approved by the minor coordinator. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/humanitarian-engineering-eng', 308, '{}'::text[], null),
('minor-landscape-architectural-studies', 'minor', 'Landscape Architectural Studies Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 12, 2.0, 'Offered by the Knowlton School. No approval needed; tell your advisor so it''s tracked on your degree audit. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to 6 credit hours. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/landscape-architectural-studies-eng', 309, '{}'::text[], null),
('minor-nuclear-engineering', 'minor', 'Nuclear Engineering Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 12, 2.0, 'Prerequisites (24+ credit hours): MATH 1151, MATH 1172 or 1152, MATH 2153 or above, PHYSICS 1250, and PHYSICS 1251 (or equivalents). Take NUCLREN 4505 before the electives. Faculty advisor: Dr. Richard Vasques (vasques.4@osu.edu). Up to 10 hours may count as technical electives in some majors. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to 6 credit hours. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/nuclear-engineering-eng', 310, '{}'::text[], null),
('minor-petroleum-engineering', 'minor', 'Petroleum Engineering Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 15, 2.0, 'Prerequisites: chemistry (CHEM 1210 and 1220 or equivalent), calculus (MATH 1151 and 1172 or equivalent), ENGR 1181 and 1182, CBE 2200, EARTHSC 1100 (or equivalent), EARTHSC 2122 and 4502. Some may be waived for declared minors with enough math and science; see Brian Endres (endres.10@osu.edu) in Chemical and Biomolecular Engineering. No substitutions for listed courses. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to 6 credit hours. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/petroleum-engineering-eng', 311, '{}'::text[], null),
('minor-robotics-and-autonomous-systems', 'minor', 'Robotics and Autonomous Systems Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 12, 2.0, 'Prerequisites: calculus (MATH 1151 and 1172 or equivalent), MATH 2174 or 2177 (or 2415 and 2568), PHYSICS 1250 or 1260, and ENGR 1221, CSE 1222, or ENGR 1281.01H. With MAE''s permission, up to 6 hours of AEROENG, CSE, ECE, ISE, or MECHENG 4998/4999 research on robot and automation systems can count as electives (RAS Minor Research Project form). Minor advisor: Dr. Haijun Su (su.298@osu.edu). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to 6 credit hours. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/robotics-and-autonomous-systems-eng', 312, '{}'::text[], null),
('minor-semiconductor-devices', 'minor', 'Semiconductor Devices Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 13, 2.0, 'Prerequisites: PHYSICS 1251 or 1261 (or 1240 and 1241), CHEM 1210, 1220, or 1250, and MATH 2415 or 2174 (before or with ECE 3030). ECE majors should pick minor courses with their advisor so they don''t interfere with the major. Advisor: Alissa Kasmer (kasmer.4@osu.edu). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/semiconductor-devices-eng', 313, '{}'::text[], null),
('minor-signal-processing', 'minor', 'Signal Processing Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 15, 2.0, 'Not open to Electrical and Computer Engineering majors. Prerequisites: calculus (MATH 1151, then 1172 or an equivalent sequence), MATH 2568 (or 2173 and 2174), PHYSICS 1250 or a chemistry equivalent, and CSE 1222 or ENGR 1281.xxH. Up to 6 credit hours may also count toward your major; check your department. Advisor: Alissa Kasmer (kasmer.4@osu.edu). Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to two courses, if the minor has at least 4 courses. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://artsandsciences.osu.edu/academics/programs/minors/signal-processing-eng', 314, array['eng-ece']::text[], null),
('minor-surveying-and-mapping', 'minor', 'Surveying and Mapping Minor', 'College of Engineering', 'College of Engineering minor advising sheets (2026)', 16, 2.0, 'Designed for Civil Engineering students who want to sit for the Fundamentals of Surveying exam. Prerequisites: MATH 1172 or 2153, and CIVILEN 2410 (open to Civil and Environmental Engineering majors). Most courses require enrollment in the Civil Engineering major; declared minors contact Liz Riter (riter.7@osu.edu) for permission. For Civil Engineering students admitted Autumn 2025 or later, all five courses also count as technical electives. Minimum C- in each course and a 2.00 GPA across all minor coursework; no Pass/Non-Pass, and at most 3 credit hours graded S/U or from X193 individual studies. Up to 6 hours of transfer or exam credit. At least 6 credit hours at the 3000 level or above; 1000-level courses don''t count. GE overlap: up to 6 credit hours. The minor must be in a different subject than the major and contain at least 12 credit hours distinct from the major and other minors.', 'https://ceg.osu.edu/degrees/minors/surveying-and-mapping-minor', 315, '{}'::text[], null)
